<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop Environment</title>
<style>
  * { box-sizing: border-box; }

  html, body {
    margin: 0; padding: 0;
    width: 100%; height: 100%;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    overflow: hidden;
    background: #000;
  }

  /* Desktop Root */
  #desktop {
    width: 100%; height: 100%;
    background: radial-gradient(circle at 50% 30%, #4b1e3d 0%, #2c001e 55%, #161616 100%);
    position: relative;
    overflow: hidden;
  }

  /* Taskbar / Top Bar */
  #taskbar {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 36px;
    background: rgba(24, 24, 24, 0.95);
    display: flex;
    align-items: center;
    padding: 0 12px;
    gap: 12px;
    border-bottom: 1px solid #000;
    z-index: 9999;
    box-shadow: 0 1px 4px rgba(0,0,0,0.5);
  }
  #taskbar button {
    background: transparent;
    color: #eee;
    border: none;
    padding: 6px 12px;
    cursor: pointer;
    border-radius: 4px;
    font-size: 14px;
    display: flex;
    align-items: center;
    gap: 6px;
  }
  #taskbar button:hover {
    background: rgba(255,255,255,0.1);
  }

  /* Windows */
  .window {
    display: none; /* hidden initially, shown via launcher */
    position: absolute;
    width: 480px;
    height: 360px; /* >= 360x240 requirement */
    background: #2b2b2b;
    border: 1px solid #111;
    border-radius: 8px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.6);
    flex-direction: column;
    overflow: hidden;
  }
  #files-window { top: 60px; left: 60px; }
  #notepad-window { top: 100px; left: 120px; }

  .title-bar {
    background: #1f1f1f;
    color: #eee;
    padding: 8px 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: move;
    user-select: none;
    border-bottom: 1px solid #000;
  }
  .title-bar span {
    font-weight: 500;
    font-size: 14px;
  }
  .title-bar .win-close {
    background: #e95420;
    border: none;
    color: white;
    border-radius: 50%;
    width: 22px; height: 22px;
    cursor: pointer;
    font-size: 14px;
    line-height: 1;
    display: flex;
    justify-content: center;
    align-items: center;
  }
  .title-bar .win-close:hover {
    background: #c93f12;
  }

  .window-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #2b2b2b;
    overflow: hidden;
  }

  /* Files App */
  .toolbar {
    padding: 8px 12px;
    background: #333;
    display: flex;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid #111;
  }
  .toolbar button {
    background: #444;
    color: #fff;
    border: 1px solid #222;
    padding: 6px 12px;
    cursor: pointer;
    border-radius: 4px;
    font-size: 13px;
  }
  .toolbar button:hover { background: #555; }
  #files-path {
    color: #ddd;
    font-family: Consolas, Monaco, monospace;
    font-size: 13px;
    background: #222;
    padding: 6px 10px;
    border-radius: 4px;
    flex: 1;
    border: 1px solid #111;
  }

  #files-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-wrap: wrap;
    align-content: flex-start;
    gap: 12px;
    background: #2b2b2b;
  }
  .fs-item {
    width: 84px;
    height: 84px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: #eee;
    cursor: default;
    border-radius: 4px;
    text-align: center;
    font-size: 13px;
    padding: 4px;
    word-break: break-word;
    line-height: 1.2;
  }
  .fs-item[data-type="folder"] {
    cursor: pointer;
  }
  .fs-item[data-type="folder"]:hover {
    background: rgba(233, 84, 32, 0.15);
    outline: 1px solid rgba(233, 84, 32, 0.4);
  }
  .fs-item[data-type="folder"]::before {
    content: "📁";
    font-size: 36px;
    margin-bottom: 6px;
  }
  .fs-item[data-type="file"]::before {
    content: "📄";
    font-size: 36px;
    margin-bottom: 6px;
  }

  /* Notepad App */
  #tabs-container {
    display: flex;
    background: #1f1f1f;
    border-bottom: 1px solid #111;
    min-height: 40px;
  }
  #tabs {
    display: flex;
    flex: 1;
    overflow-x: auto;
  }
  .tab {
    padding: 0 16px;
    background: #2b2b2b;
    color: #aaa;
    border-right: 1px solid #111;
    cursor: pointer;
    white-space: nowrap;
    display: flex;
    align-items: center;
    border-bottom: 2px solid transparent;
    font-size: 13px;
  }
  .tab:hover {
    background: #333;
    color: #eee;
  }
  .tab.active {
    background: #333;
    color: #fff;
    border-bottom: 2px solid #e95420;
  }
  #new-tab {
    background: #2b2b2b;
    color: #fff;
    border: none;
    border-left: 1px solid #111;
    padding: 0 16px;
    cursor: pointer;
    font-size: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  #new-tab:hover { background: #444; }
  #editor {
    flex: 1;
    width: 100%;
    border: none;
    resize: none;
    background: #1e1e1e;
    color: #e0e0e0;
    padding: 12px;
    font-family: Consolas, Monaco, monospace;
    font-size: 14px;
    outline: none;
    line-height: 1.5;
  }
</style>
</head>
<body>
<div id="desktop">
  <div id="taskbar">
    <button id="open-files">📁 Files</button>
    <button id="open-notepad">📝 Notepad</button>
  </div>

  <div id="files-window" class="window">
    <div class="title-bar">
      <span>Files</span>
      <button class="win-close" title="Close">×</button>
    </div>
    <div class="window-body">
      <div class="toolbar">
        <button id="files-up">↑ Up</button>
        <span id="files-path">/</span>
      </div>
      <div id="files-list"></div>
    </div>
  </div>

  <div id="notepad-window" class="window">
    <div class="title-bar">
      <span>Notepad</span>
      <button class="win-close" title="Close">×</button>
    </div>
    <div class="window-body">
      <div id="tabs-container">
        <div id="tabs"></div>
        <button id="new-tab" title="New Tab">+</button>
      </div>
      <textarea id="editor" placeholder="Type here..."></textarea>
    </div>
  </div>
</div>

<script>
(function() {
  'use strict';

  // --- Window Management ---
  let topZ = 10;
  function setupWindow(id, launcherId) {
    const win = document.getElementById(id);
    const launcher = document.getElementById(launcherId);
    const closeBtn = win.querySelector('.win-close');

    launcher.addEventListener('click', () => {
      win.style.display = 'flex';
      win.style.zIndex = ++topZ;
    });

    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      win.style.display = 'none';
    });

    const titleBar = win.querySelector('.title-bar');
    let isDragging = false;
    let offsetX, offsetY;

    titleBar.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('win-close')) return;
      isDragging = true;
      offsetX = e.clientX - win.offsetLeft;
      offsetY = e.clientY - win.offsetTop;
      win.style.zIndex = ++topZ;
    });

    document.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      win.style.left = (e.clientX - offsetX) + 'px';
      win.style.top = (e.clientY - offsetY) + 'px';
    });

    document.addEventListener('mouseup', () => {
      isDragging = false;
    });
  }

  setupWindow('files-window', 'open-files');
  setupWindow('notepad-window', 'open-notepad');

  // --- Files App ---
  const filesystem = {
    bin: {},
    etc: { 'hosts': 'file', 'passwd': 'file' },
    home: {
      user: {
        Documents: { 'notes.txt': 'file', 'resume.pdf': 'file' },
        Downloads: { 'ubuntu.iso': 'file' },
        Pictures: { 'wallpaper.png': 'file', 'avatar.jpg': 'file' },
        '.bashrc': 'file'
      }
    },
    usr: { bin: {}, lib: {}, share: {} },
    var: { log: { 'syslog': 'file' }, www: {} }
  };

  let currentPath = [];

  function renderFiles() {
    const list = document.getElementById('files-list');
    const pathEl = document.getElementById('files-path');
    list.innerHTML = '';

    const pathStr = '/' + currentPath.join('/');
    pathEl.textContent = pathStr;

    let node = filesystem;
    for (const p of currentPath) {
      node = node[p];
    }

    const entries = Object.entries(node);
    entries.sort((a, b) => {
      const aIsFolder = typeof a[1] === 'object';
      const bIsFolder = typeof b[1] === 'object';
      if (aIsFolder && !bIsFolder) return -1;
      if (!aIsFolder && bIsFolder) return 1;
      return a[0].localeCompare(b[0]);
    });

    for (const [name, val] of entries) {
      const isFolder = typeof val === 'object';
      const item = document.createElement('div');
      item.className = 'fs-item';
      item.dataset.type = isFolder ? 'folder' : 'file';
      item.textContent = name;

      if (isFolder) {
        item.addEventListener('dblclick', () => {
          currentPath.push(name);
          renderFiles();
        });
      }
      list.appendChild(item);
    }
  }

  document.getElementById('files-up').addEventListener('click', () => {
    if (currentPath.length > 0) {
      currentPath.pop();
      renderFiles();
    }
  });

  renderFiles();

  // --- Notepad App ---
  let tabs = [];
  let activeTabId = null;

  function loadState() {
    try {
      const savedTabs = localStorage.getItem('notepad_tabs');
      const savedActive = localStorage.getItem('notepad_active_tab');
      if (savedTabs) {
        const parsed = JSON.parse(savedTabs);
        if (Array.isArray(parsed)) {
          tabs = parsed;
          activeTabId = savedActive;
        }
      }
    } catch(e) {}
    if (!tabs || tabs.length === 0) {
      tabs = [{ id: 'tab_' + Date.now(), title: 'Tab 1', content: '' }];
      activeTabId = tabs[0].id;
    }
    if (!tabs.find(t => t.id === activeTabId)) {
      activeTabId = tabs[0].id;
    }
  }

  function saveNotepad() {
    try {
      localStorage.setItem('notepad_tabs', JSON.stringify(tabs));
      localStorage.setItem('notepad_active_tab', activeTabId);
    } catch(e) {}
  }

  function renderTabs() {
    const tabsEl = document.getElementById('tabs');
    tabsEl.innerHTML = '';
    tabs.forEach((tab) => {
      const tabEl = document.createElement('div');
      tabEl.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
      tabEl.textContent = tab.title;
      tabEl.addEventListener('click', () => {
        activeTabId = tab.id;
        saveNotepad();
        renderTabs();
        updateEditor();
      });
      tabsEl.appendChild(tabEl);
    });
  }

  function updateEditor() {
    const editor = document.getElementById('editor');
    const activeTab = tabs.find(t => t.id === activeTabId);
    editor.value = activeTab ? activeTab.content : '';
  }

  document.getElementById('editor').addEventListener('input', (e) => {
    const activeTab = tabs.find(t => t.id === activeTabId);
    if (activeTab) {
      activeTab.content = e.target.value;
      saveNotepad();
    }
  });

  document.getElementById('new-tab').addEventListener('click', () => {
    const id = 'tab_' + Date.now() + '_' + Math.floor(Math.random()*1000);
    const tabNum = tabs.length + 1;
    tabs.push({ id, title: 'Tab ' + tabNum, content: '' });
    activeTabId = id;
    saveNotepad();
    renderTabs();
    updateEditor();
    document.getElementById('editor').focus();
  });

  loadState();
  renderTabs();
  updateEditor();
})();
</script>
</body>
</html>
